import numpy as np
seq = ""
arr = np.array(list(seq))
window_size = 50
step = 50
for start in range(0, len(arr), step):
    window = arr[start:start+window_size]
    # after this line you can add - print(start, len(window))
    gc = ((window == "G") | (window == "C")).sum() / len(window) * 100
    # after this line you can add a print line similar to last without skew,you would get gc % but not seperately
    g_count = (window == "G").sum()
    c_count = (window == "C").sum()
    skew = (g_count - c_count) / (g_count + c_count)
    print(
        f"Bases {start + 1}-{start + len(window)}: GC {gc:.2f}%  skew {skew:.3f}")
